using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UIElements;using EchoSphere.Core;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class CampaignRegionAcceptance {public static object Main(){
if(!UnityEditor.EditorApplication.isPlaying)throw new Exception("Play required");const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;var r=UnityEngine.Object.FindAnyObjectByType<EchoSphereRuntime>();var t=r.GetType();var names=new[]{"_selectedRegion","_tutorialStep","_regionStabilized","_regionHudPocketId","_regionPocketNotice","_regionPocketNoticeTimer"};var old=new Dictionary<string,object>();foreach(var n in names)old[n]=t.GetField(n,F).GetValue(r);var player=(Transform)t.GetField("_player",F).GetValue(r);var oldPos=player.position;var field=(RegionFieldVisuals)t.GetField("_regionFieldVisuals",F).GetValue(r);var oldRegion=field.ActiveRegionId;var oldPois=field.CapturePoiState();int checks=0;
void Set(string n,object v)=>t.GetField(n,F).SetValue(r,v);void Check(bool v,string why){checks++;if(!v)throw new Exception(why);}object Call(string n,params object[] args)=>t.GetMethod(n,F).Invoke(r,args);
try{var menu=(NativeRegionScreen.State)Call("ReadNativeRegionState");Check(menu.Regions.Count==7,"six regions plus Convergence selection card");Check(menu.Regions.Select(x=>x.Id).Distinct().Count()==7,"unique region launch identities");var uiObject=new GameObject("Campaign region UI construction fixture");try{foreach(var row in menu.Regions)row.Available=true;var screen=uiObject.AddComponent<NativeRegionScreen>();screen.Show(menu,1f,()=>{},(id,mode,challenge)=>{});var root=(VisualElement)typeof(NativeRegionScreen).GetField("_root",F).GetValue(screen);foreach(var row in menu.Regions){var card=root.Q<VisualElement>("region-"+row.Id);Check(card!=null,"actual UI card "+row.Id);Check(card.Q<Button>("start-"+row.Id)!=null,"actual stabilization button "+row.Id);if(row.Challenges.Count==0)Check(card.Q<VisualElement>("region-challenge-heading")==null,"unsupported challenge controls absent");}screen.Hide();}finally{UnityEngine.Object.DestroyImmediate(uiObject);}var keys=new HashSet<string>();Set("_tutorialStep",-1);Set("_regionStabilized",true);
for(int i=0;i<6;i++){var region=(EchoRegionId)i;Set("_selectedRegion",region);string id=CampaignRegions.SourceId(region);Check(keys.Add((string)t.GetMethod("RegionStabilizedKey",F).Invoke(null,new object[]{region})),"isolated stabilization keys");var snapshot=RunSnapshotCodec.Capture(r,f=>f.Name=="_selectedRegion");Set("_selectedRegion",EchoRegionId.ResonanceBasin);RunSnapshotCodec.Restore(snapshot,t,r);Check(r.SelectedRegion==region,"selected region enum snapshot roundtrip");var schedule=RegionBossScheduleRules.Create(region);for(int time=0;time<=1800;time++)RegionBossScheduleRules.Advance(schedule,time,false);var restoredSchedule=RegionBossScheduleRules.Create();RunSnapshotCodec.Restore(RunSnapshotCodec.Capture(schedule),typeof(RegionBossScheduleState),restoredSchedule);Check(restoredSchedule.RegionId==region&&restoredSchedule.Cleared&&restoredSchedule.MajorBossesSpawned==2,"actual Editor schedule snapshot roundtrip");var config=NativeRunCatalog.Instance.GetRegion(id);Check(config.Id==id&&config.Pockets.Count==5,"native profile has selected region and five pockets");field.SetRegion(region);Check(field.ActiveRegionId==region,"radar owns selected region");if(i>=2){var profile=CampaignRegions.Get(region);var radar=(IList)typeof(RegionFieldVisuals).GetField("_pockets",F).GetValue(field);for(int k=0;k<5;k++){var p=profile.Pockets[k];Check(config.Pockets[k].Id==p.Id&&config.Pockets[k].X==p.X&&config.Pockets[k].Y==p.Y,"native world shares core pocket");var center=(Vector2)radar[k].GetType().GetField("Center",F).GetValue(radar[k]);Check(Vector2.Distance(center,new Vector2(p.X,-p.Y)*SpherePlacementRules.SourcePixelsToWorld)<.0001f,"radar world position shares core pocket");player.position=new Vector3(p.X*SpherePlacementRules.SourcePixelsToWorld,-p.Y*SpherePlacementRules.SourcePixelsToWorld,0);Call("TickRegionHudState",0f);Check((string)t.GetField("_regionHudPocketId",F).GetValue(r)==p.Id,"HUD resolves actual pocket");var hud=(NativeHudView.State)Call("ProjectNativeLiveHudState",true);Check(hud.Region==profile.Ru&&hud.Pocket.Contains(p.Ru),"RU HUD selected region/pocket");var en=(NativeHudView.State)Call("ProjectNativeLiveHudState",false);Check(en.Region==profile.En&&en.Pocket.Contains(p.En),"EN HUD selected region/pocket");}}}
var result=new{result="PASS",checks,scope="Actual six regions plus Convergence card,unique save keys,selected-region snapshot roundtrip,four new core/world/radar/HUD pocket mappings in RU/EN;no launch,no prefs writes,not a full battle or Android acceptance"};File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../Library/campaign-region-acceptance.json")),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
}finally{foreach(var n in names)Set(n,old[n]);player.position=oldPos;field.SetRegion(oldRegion);field.RestorePoiState(oldPois);}}
}
